import{_ as a,o as r,c as d,ag as e}from"./chunks/framework.qp_iHMOg.js";const u=JSON.parse('{"title":"架构师-备考 综合知识-系统基础-操作系统","description":"","frontmatter":{"title":"架构师-备考 综合知识-系统基础-操作系统"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/index.md","filePath":"综合知识/系统基础/操作系统/index.md","lastUpdated":null}'),l={name:"综合知识/系统基础/操作系统/index.md"};function o(i,t,n,h,s,p){return r(),d("div",null,[...t[0]||(t[0]=[e(`<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 进程管理（进程状态/PCB/上下文切换/通信）</li><li>[x] 进程同步（信号量/PV 操作/管程）</li><li>[x] 死锁（必要条件/银行家算法/预防与避免）</li><li>[x] 存储管理（分页/分段/段页式/虚拟内存，页面置换算法）</li><li>[x] 文件系统（目录结构/空闲空间管理）</li><li>[x] I/O 管理（SPOOLing/磁盘调度算法）</li><li>[x] 线程 vs 进程</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><blockquote><p>历年考情：每年都考 3-5 分。第二版教材只有基本概念，但历年真题需要掌握原有全部内容。较为重要：分页存储、I/O 软件。</p></blockquote><h3 id="_1-操作系统概述" tabindex="-1">1. 操作系统概述 <a class="header-anchor" href="#_1-操作系统概述" aria-label="Permalink to &quot;1. 操作系统概述&quot;">​</a></h3><p><strong>定义</strong>：能有效地组织和管理系统中的各种软/硬件资源，合理地组织计算机系统工作流程，控制程序的执行，并向用户提供良好的工作环境和友好的接口。</p><p><strong>三个作用</strong>：</p><ul><li>管理计算机中运行的程序和分配各种软硬件资源</li><li>为用户提供友善的人机界面</li><li>为应用程序的开发和运行提供高效率的平台</li></ul><p><strong>四个特征</strong>：并发性、共享性、虚拟性、不确定性</p><ul><li>并发 vs 并行：并发是宏观的（分时调度），并行是微观的</li></ul><p><strong>五大功能</strong>：</p><ul><li>进程管理 — 对 CPU 执行&quot;时间&quot;进行管理</li><li>文件管理 — 文件存储空间管理、目录管理、读写管理和存取控制</li><li>存储管理 — 对主存储器&quot;空间&quot;进行管理</li><li>设备管理 — 对硬件设备的管理，包括输入/输出设备的分配、启动、完成和回收</li><li>作业管理 — 任务、界面管理、人机交互等</li></ul><p><strong>操作系统分类</strong>：</p><table tabindex="0"><thead><tr><th>类型</th><th>特点</th></tr></thead><tbody><tr><td>批处理操作系统</td><td>单道/多道批处理（主机与外设可并行）</td></tr><tr><td>分时操作系统</td><td>CPU 时间划分为时间片，轮流为各终端服务</td></tr><tr><td>实时操作系统</td><td>在被控对象允许的时间范围内快速反应，可靠性要求高</td></tr><tr><td>网络操作系统</td><td>集中模式 / C/S 模式 / 对等模式</td></tr><tr><td>分布式操作系统</td><td>多台计算机无主次之分，通过通信交换信息</td></tr><tr><td>微机操作系统</td><td>Windows、Mac OS、Linux</td></tr></tbody></table><p><strong>嵌入式操作系统</strong>特点：微型化、可定制、实时性、可靠性、易移植性（采用 HAL 和 BSP 设计）。</p><p>初始化过程（自底向上）：片级初始化 → 板级初始化 → 系统初始化。</p><h3 id="_2-进程管理" tabindex="-1">2. 进程管理 <a class="header-anchor" href="#_2-进程管理" aria-label="Permalink to &quot;2. 进程管理&quot;">​</a></h3><h4 id="进程组成与状态" tabindex="-1">进程组成与状态 <a class="header-anchor" href="#进程组成与状态" aria-label="Permalink to &quot;进程组成与状态&quot;">​</a></h4><p><strong>进程组成</strong>：PCB（进程控制块，唯一标识）、程序（描述做什么）、数据（执行所需数据）。</p><p><strong>三态模型</strong>（必须熟练掌握转换）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>运行 → 就绪（时间片到）</span></span>
<span class="line"><span>运行 → 阻塞（等待某事件）</span></span>
<span class="line"><span>阻塞 → 就绪（等待的事件发生）</span></span>
<span class="line"><span>就绪 → 运行（被调度）</span></span></code></pre></div><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/fc91e36be89335389d25459e5b84134b_MD5.png" alt="进程三态图"></p><h4 id="前趋图" tabindex="-1">前趋图 <a class="header-anchor" href="#前趋图" aria-label="Permalink to &quot;前趋图&quot;">​</a></h4><p>详见：<a href="/arch-exam/综合知识/系统基础/操作系统/前趋图与资源图.html">架构师-备考 综合知识-系统基础-操作系统-前趋图与资源图</a></p><h4 id="进程同步与互斥" tabindex="-1">进程同步与互斥 <a class="header-anchor" href="#进程同步与互斥" aria-label="Permalink to &quot;进程同步与互斥&quot;">​</a></h4><ul><li><strong>临界资源</strong>：各进程间需要以互斥方式对其进行访问的资源</li><li><strong>临界区</strong>：进程中<strong>对临界资源实施操作的那段程序</strong></li><li><strong>互斥</strong>：同一时间只能由一个任务单独使用临界资源，使用时加锁</li><li><strong>同步</strong>：多个任务可并发执行，有速度差异，需要等待协调</li></ul><p><strong>信号量</strong>：</p><ul><li>互斥信号量：对临界资源互斥访问，<strong>初值为 1</strong></li><li>同步信号量：对共享资源的访问控制，<strong>初值一般是共享资源的数量</strong></li></ul><p><strong>P/V 操作</strong>：</p><ul><li><strong>P 操作（申请资源）</strong>：S = S - 1，若 S &gt;= 0 则继续执行；若 S &lt; 0 则阻塞，插入阻塞队列</li><li><strong>V 操作（释放资源）</strong>：S = S + 1，若 S &gt; 0 则继续执行；若 S &lt;= 0 则从阻塞队列唤醒一个进程</li></ul><p><strong>生产者-消费者问题</strong>：三个信号量 — 互斥信号量 S0（仓库使用权），同步信号量 S1（空闲位置数），同步信号量 S2（商品个数）。</p><h4 id="进程调度" tabindex="-1">进程调度 <a class="header-anchor" href="#进程调度" aria-label="Permalink to &quot;进程调度&quot;">​</a></h4><p><strong>三级调度</strong>：</p><ul><li>高级调度（作业调度）：决定哪个后备作业调入系统，成为就绪进程</li><li>中级调度（对换调度）：决定交换区中哪个就绪进程调入内存</li><li>低级调度（进程调度）：决定内存中哪个就绪进程占用 CPU，最活跃、影响最大</li></ul><p><strong>调度算法</strong>：</p><table tabindex="0"><thead><tr><th>算法</th><th>特点</th></tr></thead><tbody><tr><td>先来先服务 FCFS</td><td>先到达先分配 CPU，用于宏观调度</td></tr><tr><td>时间片轮转</td><td>每个进程分配相同时间片轮流使用 CPU，用于微观调度</td></tr><tr><td>优先级调度</td><td>优先级大的先分配 CPU</td></tr><tr><td>多级反馈调度</td><td>时间片轮转 + 优先级结合，多级队列不同优先级和时间片</td></tr></tbody></table><p>调度方式：<strong>可剥夺</strong>（高优先级进程可强行抢占 CPU）vs <strong>不可剥夺</strong>（必须等当前进程自动释放 CPU）。</p><h4 id="死锁" tabindex="-1">死锁 <a class="header-anchor" href="#死锁" aria-label="Permalink to &quot;死锁&quot;">​</a></h4><p><strong>四个必要条件</strong>：资源互斥、占有并等待、不可剥夺、环路等待。</p><p><strong>处理策略</strong>：</p><ul><li>死锁预防：破坏四个条件之一</li><li>死锁避免：银行家算法，提前计算安全序列，不安全则不分配</li><li>死锁检测：定时运行检测程序</li><li>死锁解除：强制剥夺资源、撤销进程</li></ul><p><strong>死锁资源计算</strong>：n 个进程各需 R 个资源，发生死锁的最大资源数 = n × (R-1)，不发生死锁的最小资源数 = n × (R-1) + 1。</p><h4 id="线程-vs-进程" tabindex="-1">线程 vs 进程 <a class="header-anchor" href="#线程-vs-进程" aria-label="Permalink to &quot;线程 vs 进程&quot;">​</a></h4><p>引入线程原因：进程创建、撤销和切换时空开销大，限制了并发程度。</p><table tabindex="0"><thead><tr><th></th><th>进程</th><th>线程</th></tr></thead><tbody><tr><td>资源</td><td>独立分配资源的单位</td><td>基本不拥有资源（仅 PC、寄存器、栈）</td></tr><tr><td>调度</td><td>传统上可独立调度</td><td><strong>调度和分配的基本单位</strong></td></tr><tr><td>共享</td><td>进程间资源独立</td><td>同进程线程<strong>共享</strong>进程全部资源</td></tr><tr><td>开销</td><td>创建/切换开销大</td><td>创建/切换开销小</td></tr></tbody></table><h3 id="_3-存储管理" tabindex="-1">3. 存储管理 <a class="header-anchor" href="#_3-存储管理" aria-label="Permalink to &quot;3. 存储管理&quot;">​</a></h3><h4 id="分区存储管理" tabindex="-1">分区存储管理 <a class="header-anchor" href="#分区存储管理" aria-label="Permalink to &quot;分区存储管理&quot;">​</a></h4><p><strong>整存</strong>，将进程所需内存整体一起分配。</p><table tabindex="0"><thead><tr><th>方式</th><th>特点</th></tr></thead><tbody><tr><td>固定分区</td><td>静态分区，产生内部碎片</td></tr><tr><td>可变分区</td><td>动态分区，产生外部碎片</td></tr><tr><td>可重定位分区</td><td>移动已分配区域合并碎片，仅在外部请求无法满足时触发</td></tr></tbody></table><p><strong>可变分区分配算法</strong>：</p><table tabindex="0"><thead><tr><th>算法</th><th>策略</th></tr></thead><tbody><tr><td>首次适应法</td><td>从头查找，找到第一个 &gt;= 所需空间的空间块</td></tr><tr><td>最佳适应法</td><td>空闲块按大小排序，找最接近的</td></tr><tr><td>最差适应法</td><td>找最大的空闲块，防止产生过多细小碎片</td></tr><tr><td>循环首次适应法</td><td>从上次分配位置继续查找，不每次从头开始</td></tr></tbody></table><h4 id="分页存储管理" tabindex="-1">分页存储管理 <a class="header-anchor" href="#分页存储管理" aria-label="Permalink to &quot;分页存储管理&quot;">​</a></h4><p>详见：<a href="/arch-exam/综合知识/系统基础/操作系统/分页存储管理.html">架构师-备考 综合知识-系统基础-操作系统-分页存储管理</a></p><p>逻辑页分为页号和页内地址，通过页表查询页号对应的物理块号。相关概念：页面置换算法（最优算法、先进先出、最近最少使用）、快表。</p><h4 id="分段存储管理" tabindex="-1">分段存储管理 <a class="header-anchor" href="#分段存储管理" aria-label="Permalink to &quot;分段存储管理&quot;">​</a></h4><p>将进程空间按逻辑整体分段，段表包含<strong>段长和基址</strong>两个属性来确定逻辑段在物理段中的位置。</p><ul><li>优点：多道程序共享内存，各段修改互不影响</li><li>缺点：内存利用率低，内存碎片浪费大</li></ul><blockquote><p>地址越界判断：逻辑地址 (段号, 偏移) 中偏移 &gt; 段长 则为越界。</p></blockquote><h4 id="段页式存储管理" tabindex="-1">段页式存储管理 <a class="header-anchor" href="#段页式存储管理" aria-label="Permalink to &quot;段页式存储管理&quot;">​</a></h4><p><strong>先分段，后分页</strong>。</p><ul><li>优点：空间浪费小、存储共享容易、存储保护容易、能动态链接</li><li>缺点：管理软件复杂度和开销增加，执行速度下降</li></ul><h3 id="_4-设备管理" tabindex="-1">4. 设备管理 <a class="header-anchor" href="#_4-设备管理" aria-label="Permalink to &quot;4. 设备管理&quot;">​</a></h3><h4 id="设备分类" tabindex="-1">设备分类 <a class="header-anchor" href="#设备分类" aria-label="Permalink to &quot;设备分类&quot;">​</a></h4><table tabindex="0"><thead><tr><th>分类维度</th><th>类型</th></tr></thead><tbody><tr><td>按数据组织</td><td>块设备、字符设备</td></tr><tr><td>按设备功能</td><td>输入/输出/存储/网络联网/供电设备</td></tr><tr><td>按资源分配</td><td>独占设备、共享设备、虚拟设备</td></tr><tr><td>按传输速率</td><td>低速/中速/高速设备</td></tr></tbody></table><h4 id="i-o-软件" tabindex="-1">I/O 软件 <a class="header-anchor" href="#i-o-软件" aria-label="Permalink to &quot;I/O 软件&quot;">​</a></h4><p>I/O 软件<strong>隐藏了 I/O 操作实现的细节</strong>，方便用户使用 I/O 设备。</p><p>典型流程：用户程序读文件 → 与设备无关软件检查缓存 → 若无则调用设备驱动 → 向 I/O 硬件发请求 → 用户进程阻塞 → 磁盘操作完成 → 硬件产生中断 → 中断处理程序唤醒用户进程。</p><h4 id="spooling-技术" tabindex="-1">SPOOLING 技术 <a class="header-anchor" href="#spooling-技术" aria-label="Permalink to &quot;SPOOLING 技术&quot;">​</a></h4><p>在外设上建立两个数据缓冲区（输入井/输出井），多个进程共用一台独占设备（如打印机），数据排队存储在缓冲区中自动按序处理，实现<strong>物理设备的虚拟化</strong>，每个进程感觉独占使用。</p><h3 id="_5-文件管理" tabindex="-1">5. 文件管理 <a class="header-anchor" href="#_5-文件管理" aria-label="Permalink to &quot;5. 文件管理&quot;">​</a></h3><h4 id="文件概述" tabindex="-1">文件概述 <a class="header-anchor" href="#文件概述" aria-label="Permalink to &quot;文件概述&quot;">​</a></h4><p>文件的逻辑结构：有结构的记录式文件、无结构的流式文件。</p><p>文件的物理结构（在物理存储设备上的存放方法）：</p><table tabindex="0"><thead><tr><th>结构</th><th>特点</th></tr></thead><tbody><tr><td>连续结构</td><td>逻辑连续的文件信息依次存放在连续物理块上</td></tr><tr><td>链接结构</td><td>存放在不连续物理块，每块有指针指向下一块</td></tr><tr><td>索引结构</td><td>存放在不连续物理块，系统建立索引表记录逻辑块号→物理块号映射</td></tr><tr><td>多级索引</td><td>索引表占用一个或多个物理块</td></tr></tbody></table><p>存取方法：顺序存取、随机存取。</p><h4 id="索引文件结构" tabindex="-1">索引文件结构 <a class="header-anchor" href="#索引文件结构" aria-label="Permalink to &quot;索引文件结构&quot;">​</a></h4><p>详见：<a href="/arch-exam/综合知识/系统基础/操作系统/索引文件结构.html">架构师-备考 综合知识-系统基础-操作系统-索引文件结构</a></p><h4 id="文件目录" tabindex="-1">文件目录 <a class="header-anchor" href="#文件目录" aria-label="Permalink to &quot;文件目录&quot;">​</a></h4><p>详见：<a href="/arch-exam/综合知识/系统基础/操作系统/文件目录.html">架构师-备考 综合知识-系统基础-操作系统-文件目录</a></p><h4 id="文件存储空间管理" tabindex="-1">文件存储空间管理 <a class="header-anchor" href="#文件存储空间管理" aria-label="Permalink to &quot;文件存储空间管理&quot;">​</a></h4><table tabindex="0"><thead><tr><th>方法</th><th>原理</th></tr></thead><tbody><tr><td>空闲区表</td><td>为每个连续空闲区建立表项，适用于连续文件结构</td></tr><tr><td>位示图 (Bitmap)</td><td>每一位对应一个物理块，0=空闲，1=占用</td></tr><tr><td>空闲块链</td><td>每个空闲块指向下一个空闲块，链表头指针放在特定位置</td></tr><tr><td>成组链接法</td><td>空闲块分组（如 100 块/组），每组第一块登记下一组盘块号和空闲块总数</td></tr></tbody></table><blockquote><p><strong>位示图计算</strong>：物理块号 N 在第 <code>⌊N/字长⌋</code> 个字中描述（从 0 编号即为第 <code>⌊N/字长⌋</code> 个字）。磁盘容量/物理块大小 = 物理块总数 → 除以字长 = 位示图所需字数。</p></blockquote>`,82)])])}const c=a(l,[["render",o]]);export{u as __pageData,c as default};
